import React, { useEffect, useRef, useState, useCallback } from 'react';
import gsap from 'gsap';
import { Play, Pause, ChevronRight } from 'lucide-react';
import GlobeScene from './GlobeScene';
import OrbitNavigation from './OrbitNavigation';

// ============================================================================
// HERO COMPONENT (Exact Sequenced Intro -> 3D Celestial Planet)
// ============================================================================
// Precise Flow:
// 1. technospark animation: Video background + 3D title entrance.
// 2. blank screen: Video & title fade out completely -> Clean blank dark pause.
// 3. logo and name: Top-left logo + Technospark name appears.
// 4. globe: 3D Celestial Planet + Orbit Navigation emerge in the center.
// ============================================================================

export default function Hero({ onShowLogo }) {
  const heroRef = useRef(null);
  const videoRef = useRef(null);
  const videoWrapRef = useRef(null);
  const introWrapRef = useRef(null);
  const technoRef = useRef(null);
  const sparkRef = useRef(null);
  const taglineRef = useRef(null);
  const skipBtnRef = useRef(null);
  const globeWrapperRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(true);
  const [isManuallyPaused, setIsManuallyPaused] = useState(false);
  const [introCompleted, setIntroCompleted] = useState(false);

  const tlRef = useRef(null);

  // Keep onShowLogo callback reference stable so state changes never restart timeline
  const onShowLogoRef = useRef(onShowLogo);
  useEffect(() => {
    onShowLogoRef.current = onShowLogo;
  });

  // 1. Orchestrated GSAP Timeline: Title -> Blank Screen -> Logo -> Globe
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setIntroCompleted(true);
      if (videoRef.current) videoRef.current.pause();
      if (videoWrapRef.current) videoWrapRef.current.style.display = 'none';
      if (introWrapRef.current) introWrapRef.current.style.display = 'none';
      if (globeWrapperRef.current) {
        gsap.set(globeWrapperRef.current, { opacity: 1, scale: 1, pointerEvents: 'auto', filter: 'blur(0px)' });
      }
      onShowLogoRef.current?.();
      return;
    }

    const ctx = gsap.context(() => {
      // Set initial states
      gsap.set(globeWrapperRef.current, {
        opacity: 0,
        scale: 0.85,
        pointerEvents: 'none',
        filter: 'blur(10px)'
      });
      gsap.set(taglineRef.current, { opacity: 0, y: 16, filter: 'blur(6px)' });
      gsap.set(skipBtnRef.current, { opacity: 0, y: 10 });

      const tl = gsap.timeline({
        defaults: { ease: 'power3.out' },
        onComplete: () => {
          setIntroCompleted(true);
          if (videoRef.current) videoRef.current.pause();
          if (videoWrapRef.current) videoWrapRef.current.style.display = 'none';
          if (introWrapRef.current) introWrapRef.current.style.display = 'none';
        }
      });
      tlRef.current = tl;

      // ── 1. TECHNOSPARK ANIMATION (Video background + Center 3D title) ─────
      tl.fromTo(
        technoRef.current,
        { opacity: 0, scale: 1.4, rotateX: 45, y: -40, filter: 'blur(20px)' },
        { opacity: 1, scale: 1, rotateX: 0, y: 0, filter: 'blur(0px)', duration: 1.0, ease: 'back.out(1.5)' },
        0.15
      )
      .fromTo(
        sparkRef.current,
        { opacity: 0, scale: 0.6, rotateY: -35, y: 40, filter: 'blur(20px)' },
        { opacity: 1, scale: 1, rotateY: 0, y: 0, filter: 'blur(0px)', duration: 0.9, ease: 'elastic.out(1, 0.65)' },
        0.45
      )
      .to(
        taglineRef.current,
        { opacity: 1, y: 0, filter: 'blur(0px)', duration: 0.65, ease: 'power2.out' },
        0.75
      )
      .to(
        skipBtnRef.current,
        { opacity: 0.75, y: 0, duration: 0.45, ease: 'power2.out' },
        0.95
      )

      // Hold on the title animation
      .to({}, { duration: 1.1 })

      // ── 2. BLANK SCREEN (Video & Title fade out -> clean blank dark screen)
      .to(
        videoWrapRef.current,
        {
          opacity: 0,
          duration: 0.65,
          ease: 'power2.inOut',
          onComplete: () => {
            if (videoRef.current) videoRef.current.pause();
          }
        }
      )
      .to(
        introWrapRef.current,
        {
          opacity: 0,
          scale: 1.06,
          filter: 'blur(16px)',
          duration: 0.65,
          ease: 'power2.inOut',
          onComplete: () => {
            if (introWrapRef.current) introWrapRef.current.style.display = 'none';
          }
        },
        '<'
      )

      // Dedicated blank screen pause
      .to({}, { duration: 0.45 })

      // ── 3. LOGO AND NAME (Appears on top-left) ────────────────────────────
      .call(() => {
        onShowLogoRef.current?.();
      })

      // Brief pause while logo establishes
      .to({}, { duration: 0.35 })

      // ── 4. GLOBE (3D Celestial Planet emerges in center) ──────────────────
      .to(
        globeWrapperRef.current,
        {
          opacity: 1,
          scale: 1,
          filter: 'blur(0px)',
          duration: 1.2,
          ease: 'power3.out',
          pointerEvents: 'auto'
        }
      );
    }, heroRef);

    return () => ctx.revert();
  }, []); // Run ONCE on mount — completely immune to re-renders

  // Skip immediately to the globe view
  const handleSkipIntro = useCallback(() => {
    if (tlRef.current && !introCompleted) {
      tlRef.current.seek(tlRef.current.duration());
      setIntroCompleted(true);
      if (videoRef.current) videoRef.current.pause();
      if (videoWrapRef.current) videoWrapRef.current.style.display = 'none';
      if (introWrapRef.current) introWrapRef.current.style.display = 'none';
      if (globeWrapperRef.current) {
        gsap.set(globeWrapperRef.current, { opacity: 1, scale: 1, filter: 'blur(0px)', pointerEvents: 'auto' });
      }
      onShowLogoRef.current?.();
    }
  }, [introCompleted]);

  // Viewport-aware autoplay for the video during intro
  useEffect(() => {
    const video = videoRef.current;
    const heroEl = heroRef.current;
    if (!video || !heroEl || introCompleted) return;

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      video.pause();
      setIsPlaying(false);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const [entry] = entries;
        if (entry.isIntersecting) {
          if (!isManuallyPaused && !introCompleted) {
            video.play().then(() => setIsPlaying(true)).catch(() => {});
          }
        } else {
          video.pause();
          setIsPlaying(false);
        }
      },
      { threshold: 0.08, rootMargin: '0px' }
    );

    observer.observe(heroEl);
    return () => observer.disconnect();
  }, [isManuallyPaused, introCompleted]);

  // Toggle video playback manually during intro
  const togglePlayPause = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;

    if (video.paused) {
      video.play().then(() => {
        setIsPlaying(true);
        setIsManuallyPaused(false);
      }).catch(() => {});
    } else {
      video.pause();
      setIsPlaying(false);
      setIsManuallyPaused(true);
    }
  }, []);

  return (
    <section
      id="hero"
      ref={heroRef}
      className={`hero-craft-section spiderverse-hero home-hero-fullscreen ${introCompleted ? 'hero-globe-active' : 'hero-intro-active'}`}
      aria-label="Technospark 3D Portal"
    >
      {/* ── Background Video Layer (Strictly for starting animation) ──── */}
      {!introCompleted && (
        <div ref={videoWrapRef} className="hero-bg-video-wrapper">
          <video
            ref={videoRef}
            src="/assets/bg-video.mp4"
            poster="/assets/bg-video-poster.jpg"
            autoPlay
            loop
            muted
            playsInline
            preload="metadata"
            disablePictureInPicture
            disableRemotePlayback
            className="hero-bg-video-element"
          />
          <div className="hero-bg-vignette-overlay" aria-hidden="true" />

          {/* Manual Play/Pause Pill strictly during video intro */}
          <button
            type="button"
            onClick={togglePlayPause}
            className="hero-video-toggle-btn"
            aria-label={isPlaying ? 'Pause background video' : 'Play background video'}
          >
            {isPlaying ? <Pause size={12} /> : <Play size={12} />}
            <span>{isPlaying ? 'Pause' : 'Play'}</span>
          </button>
        </div>
      )}

      {/* ── 1. Start Animation: TECHNOSPARK Typography ───────────────────── */}
      {!introCompleted && (
        <div
          ref={introWrapRef}
          className="hero-intro-overlay"
          onClick={handleSkipIntro}
          title="Click to explore 3D Globe"
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') handleSkipIntro();
          }}
        >
          <div className="spiderverse-text-wrap tilt-3d-card">
            <h1 ref={technoRef} className="spiderverse-line spiderverse-techno">
              TECHNO
            </h1>
            <h1 ref={sparkRef} className="spiderverse-line spiderverse-spark">
              SPARK
            </h1>
          </div>

          <p ref={taglineRef} className="hero-intro-tagline">
            WHERE IDEAS MEET TECHNOLOGY.
          </p>

          <button
            ref={skipBtnRef}
            type="button"
            className="hero-intro-skip-hint"
            onClick={(e) => {
              e.stopPropagation();
              handleSkipIntro();
            }}
          >
            <span>Explore 3D Globe</span>
            <ChevronRight size={14} />
          </button>
        </div>
      )}

      {/* ── 4. 3D Celestial Planet + Tightly Positioned Orbit Navigation ── */}
      <div ref={globeWrapperRef} className="hero-globe-wrapper hero-globe-prominent">
        {/* Three.js 3D Celestial Planet */}
        <GlobeScene />

        {/* Orbiting Satellite Navigation Links hugging the planet */}
        <div className="hero-orbit-overlay">
          <OrbitNavigation />
        </div>
      </div>
    </section>
  );
}
