import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

// ============================================================================
// 3D GLOBE SCENE COMPONENT (From D:\frontend demo)
// ============================================================================
// Features:
// 1. Digital Wireframe Grid (Latitude and Longitude in neon violet/purple)
// 2. Inner Sphere with Deep Cosmic Shading (0x0e071e / 0x160b2b)
// 3. Surface Star / City Nodes Particles (Fibonacci distribution, cyan & violet)
// 4. Atmospheric Outer Glow
// 5. Dual Orbital Rings (Primary in neon purple, outer in cyber cyan)
// 6. Glowing Satellite Nodes traveling in orbit
// 7. Interactive mouse parallax interpolation and continuous smooth rotation
// ============================================================================

export default function GlobeScene({ onGlobeClick }) {
  const mountRef = useRef(null);
  const [webglSupported, setWebglSupported] = useState(true);

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    // Check WebGL support
    try {
      const testCanvas = document.createElement('canvas');
      const gl = testCanvas.getContext('webgl') || testCanvas.getContext('experimental-webgl');
      if (!gl) {
        setWebglSupported(false);
        return;
      }
    } catch {
      setWebglSupported(false);
      return;
    }

    let width = container.clientWidth || 850;
    let height = container.clientHeight || 850;

    // Three.js Scene, Camera, Renderer
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
    camera.position.z = 7.2;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.domElement.style.overflow = 'visible';
    renderer.domElement.style.outline = 'none';
    container.appendChild(renderer.domElement);

    // Main Globe Group
    const globeGroup = new THREE.Group();
    scene.add(globeGroup);

    // 1. Digital Wireframe Grid (Latitude and Longitude)
    const sphereRadius = 1.6;
    const sphereGeo = new THREE.SphereGeometry(sphereRadius, 32, 24);
    const wireframeGeo = new THREE.WireframeGeometry(sphereGeo);
    const wireframeMat = new THREE.LineBasicMaterial({
      color: 0x7c3aed,
      transparent: true,
      opacity: 0.38,
      linewidth: 1
    });
    const wireframe = new THREE.LineSegments(wireframeGeo, wireframeMat);
    globeGroup.add(wireframe);

    // 2. Inner Sphere with Deep Cosmic Shading
    const innerGeo = new THREE.SphereGeometry(sphereRadius * 0.985, 48, 48);
    const innerMat = new THREE.MeshPhongMaterial({
      color: 0x0e071e,
      emissive: 0x160b2b,
      specular: 0xa855f7,
      shininess: 45,
      transparent: true,
      opacity: 0.88
    });
    const innerSphere = new THREE.Mesh(innerGeo, innerMat);
    globeGroup.add(innerSphere);

    // 3. Surface Star / City Nodes Particles
    const nodeCount = 180;
    const nodePositions = new Float32Array(nodeCount * 3);
    const nodeColors = new Float32Array(nodeCount * 3);

    const cyanColor = new THREE.Color(0x22d3ee);
    const violetColor = new THREE.Color(0xc084fc);

    for (let i = 0; i < nodeCount; i++) {
      const phi = Math.acos(-1 + (2 * i) / nodeCount);
      const theta = Math.sqrt(nodeCount * Math.PI) * phi;

      const x = (sphereRadius + 0.02) * Math.cos(theta) * Math.sin(phi);
      const y = (sphereRadius + 0.02) * Math.sin(theta) * Math.sin(phi);
      const z = (sphereRadius + 0.02) * Math.cos(phi);

      nodePositions[i * 3] = x;
      nodePositions[i * 3 + 1] = y;
      nodePositions[i * 3 + 2] = z;

      const c = Math.random() > 0.4 ? violetColor : cyanColor;
      nodeColors[i * 3] = c.r;
      nodeColors[i * 3 + 1] = c.g;
      nodeColors[i * 3 + 2] = c.b;
    }

    const nodeGeo = new THREE.BufferGeometry();
    nodeGeo.setAttribute('position', new THREE.BufferAttribute(nodePositions, 3));
    nodeGeo.setAttribute('color', new THREE.BufferAttribute(nodeColors, 3));

    const nodeMat = new THREE.PointsMaterial({
      size: 0.065,
      vertexColors: true,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending
    });
    const nodes = new THREE.Points(nodeGeo, nodeMat);
    globeGroup.add(nodes);

    // 4. Atmospheric Outer Glow
    const glowGeo = new THREE.SphereGeometry(sphereRadius * 1.15, 32, 32);
    const glowMat = new THREE.MeshBasicMaterial({
      color: 0x9047ff,
      transparent: true,
      opacity: 0.12,
      side: THREE.BackSide,
      blending: THREE.AdditiveBlending
    });
    const glowSphere = new THREE.Mesh(glowGeo, glowMat);
    globeGroup.add(glowSphere);

    // 5. Orbital Rings (Tilted rings surrounding the globe)
    const ringGroup = new THREE.Group();
    scene.add(ringGroup);

    // Primary Ring
    const ringRadius = sphereRadius * 1.62;
    const ringGeo = new THREE.RingGeometry(ringRadius - 0.015, ringRadius + 0.015, 96);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xa855f7,
      transparent: true,
      opacity: 0.45,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending
    });
    const primaryRing = new THREE.Mesh(ringGeo, ringMat);
    primaryRing.rotation.x = Math.PI / 2.3;
    primaryRing.rotation.y = -Math.PI / 6;
    ringGroup.add(primaryRing);

    // Secondary Outer Ring
    const outerRingRadius = sphereRadius * 1.95;
    const outerRingGeo = new THREE.RingGeometry(outerRingRadius - 0.01, outerRingRadius + 0.01, 96);
    const outerRingMat = new THREE.MeshBasicMaterial({
      color: 0x22d3ee,
      transparent: true,
      opacity: 0.25,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending
    });
    const outerRing = new THREE.Mesh(outerRingGeo, outerRingMat);
    outerRing.rotation.x = Math.PI / 1.9;
    outerRing.rotation.y = Math.PI / 4.5;
    ringGroup.add(outerRing);

    // 6. Glowing Satellite Nodes traveling in orbit
    const satCount = 4;
    const satellites = [];
    for (let i = 0; i < satCount; i++) {
      const satGeo = new THREE.SphereGeometry(0.045, 16, 16);
      const satMat = new THREE.MeshBasicMaterial({
        color: i % 2 === 0 ? 0x22d3ee : 0xc084fc,
        blending: THREE.AdditiveBlending
      });
      const satMesh = new THREE.Mesh(satGeo, satMat);
      scene.add(satMesh);
      satellites.push({
        mesh: satMesh,
        radius: i % 2 === 0 ? ringRadius : outerRingRadius,
        speed: (0.5 + i * 0.2) * (i % 2 === 0 ? 1 : -1),
        offset: (i * Math.PI) / 2,
        inclination: i % 2 === 0 ? Math.PI / 2.3 : Math.PI / 1.9,
        rotationY: i % 2 === 0 ? -Math.PI / 6 : Math.PI / 4.5
      });
    }

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x7c3aed, 0.8);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xc084fc, 2.2);
    dirLight1.position.set(5, 3, 5);
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0x22d3ee, 1.2);
    dirLight2.position.set(-5, -2, -3);
    scene.add(dirLight2);

    // Mouse Interaction Parallax
    let mouseX = 0;
    let mouseY = 0;
    let targetRotationX = 0.2;
    let targetRotationY = 0;

    const handleMouseMove = (e) => {
      const rect = container.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const y = -(((e.clientY - rect.top) / rect.height) * 2 - 1);
      mouseX = x * 0.35;
      mouseY = y * 0.25;
    };

    window.addEventListener('mousemove', handleMouseMove);

    // Resize Handler with ResizeObserver
    const handleResize = () => {
      if (!container) return;
      width = container.clientWidth || 600;
      height = container.clientHeight || 600;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    window.addEventListener('resize', handleResize);

    let resizeObserver = null;
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(() => {
        handleResize();
      });
      resizeObserver.observe(container);
    }

    // Animation Loop
    let animationId;
    let clock = new THREE.Clock();

    const animate = () => {
      animationId = requestAnimationFrame(animate);
      const elapsed = clock.getElapsedTime();

      // Smooth globe rotation
      globeGroup.rotation.y += 0.0035;

      // Mouse responsive interpolation
      targetRotationY += (mouseX - targetRotationY) * 0.05;
      targetRotationX += (mouseY - targetRotationX) * 0.05;

      globeGroup.rotation.x = 0.2 + targetRotationX * 0.35;
      globeGroup.position.x = targetRotationY * 0.2;

      // Animate orbiting satellites
      satellites.forEach((sat) => {
        const angle = elapsed * sat.speed + sat.offset;
        const localX = sat.radius * Math.cos(angle);
        const localY = sat.radius * Math.sin(angle);

        const pos = new THREE.Vector3(localX, localY, 0);
        pos.applyAxisAngle(new THREE.Vector3(1, 0, 0), sat.inclination);
        pos.applyAxisAngle(new THREE.Vector3(0, 1, 0), sat.rotationY);

        sat.mesh.position.copy(pos);
      });

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
      if (resizeObserver) resizeObserver.disconnect();
      cancelAnimationFrame(animationId);
      if (renderer.domElement && container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      // Dispose Three.js objects
      sphereGeo.dispose();
      wireframeGeo.dispose();
      wireframeMat.dispose();
      innerGeo.dispose();
      innerMat.dispose();
      nodeGeo.dispose();
      nodeMat.dispose();
      glowGeo.dispose();
      glowMat.dispose();
      ringGeo.dispose();
      ringMat.dispose();
      outerRingGeo.dispose();
      outerRingMat.dispose();
      renderer.dispose();
    };
  }, []);

  if (!webglSupported) {
    return (
      <div
        style={{
          width: '100%',
          height: '100%',
          minHeight: '420px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative'
        }}
      >
        <div
          style={{
            width: '320px',
            height: '320px',
            borderRadius: '50%',
            background: 'radial-gradient(circle at 35% 35%, #7c3aed 0%, #160b2b 60%, #05040a 100%)',
            boxShadow: '0 0 50px rgba(124, 58, 237, 0.4), inset 0 0 30px rgba(34, 211, 238, 0.3)',
            border: '2px solid rgba(168, 85, 247, 0.4)',
            position: 'relative',
            animation: 'pulseGlow 4s infinite ease-in-out'
          }}
        >
          <div
            style={{
              position: 'absolute',
              inset: '-20px',
              border: '1px dashed rgba(192, 132, 252, 0.4)',
              borderRadius: '50%',
              animation: 'orbitSpin 20s linear infinite'
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <div
      ref={mountRef}
      className="globe-scene-mount"
      style={{
        width: '100%',
        height: '100%',
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'grab'
      }}
      title="Interactive TechnoSpark Cosmic Globe — Drag or hover to explore"
      onClick={onGlobeClick}
    />
  );
}
